const fs = require('fs');
const path = require('path');

// Load prompt from file — same pattern as workflow 03
const workspaceDir = process.cwd();
const promptPath = path.join(workspaceDir, 'prompts', 'email_generation.txt');
const prompt = fs.readFileSync(promptPath, 'utf8');

const item = $input.item;
const lead = item.json;

// Extract required fields — no hardcoded fallback strings here.
// Whatever the current email_generation.txt prompt does with an empty
// owner_name/industry is up to that prompt's own rules.
const business_name = lead.name || '';
const owner_name = lead.owner_name || '';
const city = lead.address || '';
const industry = lead.category || '';
const weak_reason = lead.weak_reason || '';
const website_url = lead.website || '';
const sender_name = 'Adrians';
const sender_email = 'adrians.stepe@gmail.com';

const leadData = {
  business_name: business_name,
  owner_name: owner_name,
  city: city,
  industry: industry,
  weak_reason: weak_reason,
  website_url: website_url,
  sender_name: sender_name,
  sender_email: sender_email
};

const fullPrompt = prompt + "\n\n---\n\n**GENERATE THE EMAIL FOR THIS LEAD OUTPUT ONLY VALID JSON:**\n" + JSON.stringify(leadData);

const body = {
  model: "gpt-4o-mini",
  messages: [{ role: "user", content: fullPrompt }],
  response_format: { type: "json_object" },
  temperature: 0.7,
  max_tokens: 4096
};

return [{
  json: {
    ...lead,
    openai_body: body
  }
}];

const item = $input.item;
const response = item.json;

// Keep original lead data (we passed it through the HTTP node or can access prior node)
const prevData = {
  name: $('Build OpenAI Request').item.json.name,
  website: $('Build OpenAI Request').item.json.website,
  email: $('Build OpenAI Request').item.json.email,
  weak_reason: $('Build OpenAI Request').item.json.weak_reason
};

let emailJson = null;

try {
  let text = response.choices[0].message.content;

  // Clean up markdown formatting if OpenAI returned it despite application/json mime type
  if (text.startsWith('```json')) {
    text = text.substring(7);
  } else if (text.startsWith('```')) {
    text = text.substring(3);
  }

  if (text.endsWith('```\n')) {
    text = text.substring(0, text.length - 4);
  } else if (text.endsWith('```')) {
    text = text.substring(0, text.length - 3);
  }

  emailJson = JSON.parse(text);
} catch (e) {
  console.log('Failed to parse OpenAI JSON: ' + e.message);
}

if (!emailJson || !emailJson.subject || !emailJson.body) {
  return [{
    json: {
      ...prevData,
      status: 'generation_failed'
    }
  }];
}

return [{
  json: {
    ...prevData,
    email_subject: emailJson.subject,
    email_body: emailJson.body,
    status: 'email_generated'
  }
}];

const prevData = $('Build OpenAI Request').item.json;

return [{
  json: {
    ...prevData,
    openai_error: $input.item.json.message || 'Unknown OpenAI error',
    status: 'generation_failed'
  }
}];

const items = $input.all();
let success = 0;
let failed = 0;

for (const item of items) {
  if (item.json.status === 'email_generated') {
    success++;
  } else {
    failed++;
  }
}

return [{
  json: {
    summary: 'Workflow 04 Complete',
    generated_emails: success,
    failed_generations: failed
  }
}];
